```javascript
import {
  MeshBasicNodeMaterial,
  MeshStandardNodeMaterial,
  PlaneGeometry,
  DoubleSide,
  Mesh,
} from 'three/webgpu';
import {
  uniform,
  texture,
  uv,
  vec2,
  vec3,
  vec4,
  mix,
  smoothstep,
  color,
  time,
  positionGeometry,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { color: ink, paper, accent, surface } = config.intent?.visualSpec?.colors || {};
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headline = items.find((i) => i.role === 'headline');
  const headlineText = headline?.text || '';

  const group = new ctx.THREE.Group();
  group.name = 'hub-journal-card-3';

  // --- Card background plane ---
  const geo = new PlaneGeometry(1.8, 1.2 * 1.618);
  const cardMat = new MeshStandardNodeMaterial({
    color: surface || '#0b0b10',
    roughness: 0.55,
    metalness: 0.35,
    clearcoat: 0.2,
    side: DoubleSide,
  });

  const card = new Mesh(geo, cardMat);
  card.position.z = 0;
  group.add(card);

  // --- Accent edge (focal strip on left) ---
  const edgeGeo = new PlaneGeometry(0.04, 1.2 * 1.618);
  const edgeMat = new MeshBasicNodeMaterial({
    color: accent || '#ff2a38',
    transparent: true,
    opacity: 0.9,
    side: DoubleSide,
  });
  const edge = new Mesh(edgeGeo, edgeMat);
  edge.position.set(-0.9, 0, 0.01);
  group.add(edge);

  // --- Image plane (loaded from imageUrl) ---
  const imagePlaneGeo = new PlaneGeometry(1.6, 1.2 * 1.618 - 0.3);
  const imageMat = new MeshBasicNodeMaterial({
    transparent: true,
    side: DoubleSide,
  });
  const imagePlane = new Mesh(imagePlaneGeo, imageMat);
  imagePlane.position.set(0, 0.3, 0.01);
  group.add(imagePlane);

  // Load texture
  const imageUrl = config.imageUrl || '/prism-mock/home/nodes/floating-accent.png';
  ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
    tex.colorSpace = 'srgb-linear';
    imageMat.map = tex;
    imageMat.needsUpdate = true;
  });

  // --- Text: headline ---
  if (headlineText) {
    const textNode = ctx.fontAtlas.createText(headlineText, {
      fontSize: 0.34,
      color: paper || '#e8ecf2',
      align: 'center',
      maxWidthPx: 1.4,
      letterSpacingPx: 0.05 * 0.34,
    });
    textNode.position.set(0, -0.45, 0.02);
    textNode.scale.set(0.8, 0.8, 0.8);
    group.add(textNode);
  }

  // --- Interaction handlers ---
  const handlers = {};
  const timelines = [];

  // Hover: subtle rise-in (0.15 scene units)
  handlers.onPointerEnter = () => {
    gsap.killTweensOf(card.position);
    const tl = gsap.timeline();
    tl.to(card.position, {
      y: 0.15,
      duration: 0.5,
      ease: 'power3.out',
      overwrite: true,
    });
    tl.to(edge.material, {
      opacity: 1.0,
      duration: 0.3,
      ease: 'power2.out',
    }, 0);
    tl.to(card.scale, {
      x: 1.02,
      y: 1.02,
      duration: 0.5,
      ease: 'power3.out',
    }, 0);
    timelines.push(tl);
  };

  handlers.onPointerLeave = () => {
    gsap.killTweensOf(card.position);
    const tl = gsap.timeline();
    tl.to(card.position, {
      y: 0,
      duration: 0.4,
      ease: 'power3.out',
      overwrite: true,
    });
    tl.to(edge.material, {
      opacity: 0.9,
      duration: 0.3,
      ease: 'power2.out',
    }, 0);
    tl.to(card.scale, {
      x: 1,
      y: 1,
      duration: 0.4,
      ease: 'power3.out',
    }, 0);
    timelines.push(tl);
  };

  // Click: press-down + emit
  handlers.onClick = () => {
    const tl = gsap.timeline();
    tl.to(card.scale, {
      x: 0.97,
      y: 0.97,
      duration: 0.12,
      ease: 'power3.out',
      overwrite: true,
    });
    tl.to(card.scale, {
      x: 1,
      y: 1,
      duration: 0.2,
      ease: 'power3.out',
    });
    tl.call(() => {
      ctx.emit('hub-journal.select', { cardId: 'hub-journal-card-3', title: headlineText });
    });
    timelines.push(tl);
  };

  group.userData.handlers = handlers;

  // --- Cleanup ---
  group.userData.cleanup = () => {
    timelines.forEach((tl) => {
      try { tl.kill(); } catch (_) {}
    });
    [cardMat, edgeMat, imageMat].forEach((mat) => {
      if (mat.map) mat.map.dispose();
      mat.dispose();
    });
    geo.dispose();
    edgeGeo.dispose();
    imagePlaneGeo.dispose();
    card.removeFromParent();
    edge.removeFromParent();
    imagePlane.removeFromParent();
    group.removeFromParent();
  };

  return group;
}
